package com.lexorion.workforce.api;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.ConstraintViolationException;import java.time.Instant;import java.util.Map;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
@RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(WorkforceException.class)ResponseEntity<?> workforce(WorkforceException e,HttpServletRequest r){return response(e.status(),e.getMessage(),r);}@ExceptionHandler({MethodArgumentNotValidException.class,ConstraintViolationException.class,MethodArgumentTypeMismatchException.class})ResponseEntity<?> validation(Exception e,HttpServletRequest r){return response(400,"Validation failed",r);}private ResponseEntity<?> response(int status,String message,HttpServletRequest r){return ResponseEntity.status(status).body(Map.of("timestamp",Instant.now(),"status",status,"errorCode","LEX-"+status,"message",message,"path",r.getRequestURI(),"correlationId",java.util.Objects.toString(org.slf4j.MDC.get("correlationId"),"")));}}
